import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it)); X = int(next(it)); Y = int(next(it))
    S = next(it).strip(); T = next(it).strip()
    if S == T:
        print("Yes")
        return
    if X + Y > N:
        print("No")
        return
    zS = S.count('0')
    zT = T.count('0')
    if X == Y:
        print("Yes" if zS == zT else "No")
        return
    D = abs(Y - X)
    if abs(zS - zT) % D != 0:
        print("No")
        return
    # check if at least one operation can be applied
    can = False
    s = S
    for i in range(N - X - Y + 1):
        if s[i:i+X] == '0'*X and s[i+X:i+X+Y] == '1'*Y:
            can = True
            break
        if s[i:i+Y] == '1'*Y and s[i+Y:i+Y+X] == '0'*X:
            can = True
            break
    if can:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

