import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    N, X, Y = map(int, data[:3])
    S = data[3]
    T = data[4]

    # If no operation can be applied
    if X + Y > N:
        print("Yes" if S == T else "No")
        return

    # Compute gcd of X and Y
    a, b = X, Y
    while b:
        a, b = b, a % b
    g = a

    # Count ones in each residue class modulo g
    ones_s = [0] * g
    ones_t = [0] * g
    for i in range(N):
        if S[i] == '1':
            ones_s[i % g] += 1
        if T[i] == '1':
            ones_t[i % g] += 1

    # It's possible iff counts match in every residue class
    if ones_s == ones_t:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
